"""notation.md is generated by tools/build_notation_page.py and must be current.

The page lists every row of tests/notation_global.txt, tests/notation_exceptions.txt and each chapter's
notation-local.md; regenerate it with `python tools/build_notation_page.py` after changing any of them.
"""
from tools.build_notation_page import PAGE, build, chapters, exception_rows
from tools.notation_tables import global_rows, local_rows


def test_committed_page_is_the_generated_page():
    assert PAGE.read_text(encoding="utf-8") == build(), "run: python tools/build_notation_page.py"


def test_page_lists_every_row_of_the_sources():
    lines = PAGE.read_text(encoding="utf-8").splitlines()
    rows = [(s, "global") for s, _ in global_rows()] + [(s, "exception") for s, _, _ in exception_rows()]
    rows += [(s, chapter.name) for chapter in chapters() for s, _ in local_rows(chapter)]
    missing = [r for r in rows if not any(line.startswith(f"| ${r[0]}$ |") for line in lines)]
    assert not missing
    table_rows = [line for line in lines if line.startswith("| $")]
    assert len(table_rows) == len(rows)
